WITH prepared AS (SELECT jsonb_array_elements('[{"slug":"agricultural-water-withdrawals-share","intro":"حصة المياه العذبة المسحوبة للاستخدامات الزراعية من إجمالي كميات السحب المقدر لجميع القطاعات، وليس نسبة الموارد المائية المتجددة. آخر رقم منشور لليمن هو 90.74 % من سحب المياه العذبة في سنة القياس 2022 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد على فهم توزيع الطلب على المياه بين الزراعة والاستعمالات الأخرى، ويبرز أهمية إدارة الري وكفاءة استخدام الموارد في اليمن.","historical_context":"من النقاط الزمنية المسجلة: 1990 (92.09 % من سحب المياه العذبة)، و2006 (90.74 % من سحب المياه العذبة)، و2022 (90.74 % من سحب المياه العذبة). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا يقيس كمية المياه التي تستهلكها كل مزرعة أو المسحوبات غير المرصودة ولا يؤكد استدامة المخزون الجوفي؛ فالسحب يختلف عن الاستهلاك الصافي والتغذية الطبيعية. تعكس أحدث قيمة سنة 2022، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأغذية والزراعة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأغذية والزراعة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ER.H2O.FWAG.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"arable-land-share","intro":"حصة مساحة الأراضي القابلة لزراعة المحاصيل المؤقتة ضمن إجمالي مساحة اليابسة وفق تصنيف استخدام الأراضي لدى المصدر. آخر رقم منشور لليمن هو 2.16 % من مساحة الأرض في سنة القياس 2024 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تساعد على فهم القاعدة الأرضية للإنتاج الزراعي ومحدودية الأراضي القابلة للزراعة في سياق الموارد المائية وطبيعة التضاريس.","historical_context":"من النقاط الزمنية المسجلة: 1990 (2.88 % من مساحة الأرض)، و2007 (2.5 % من مساحة الأرض)، و2024 (2.16 % من مساحة الأرض). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا تساوي المساحة المزروعة فعلياً في موسم معين، ولا تقيس خصوبة الأرض أو توافر مياه الري أو ملكية الأراضي. التغير في التعريف أو القياس قد يغير النسبة. تعكس أحدث قيمة سنة 2024، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأغذية والزراعة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأغذية والزراعة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/AG.LND.ARBL.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"average-annual-precipitation","intro":"مقياس لمتوسط الهطول المطري السنوي على مساحة الدولة وفق المرجع المناخي المستخدم، وليس مجموع مطر سقط كل سنة منفردة. آخر رقم منشور لليمن هو 167 ملليمتر سنويا في سنة القياس 2022 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد على وصف الظروف المناخية العامة عند دراسة الزراعة والمياه والتوزيع الجغرافي للأمطار، مع مراعاة الطبيعة الجبلية والصحراوية.","historical_context":"من النقاط الزمنية المسجلة: 1990 (167 ملليمتر سنويا)، و2006 (167 ملليمتر سنويا)، و2022 (167 ملليمتر سنويا). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"تُظهر سلسلة 967 الرقم نفسه عبر سنوات متعددة؛ وهذا يتفق مع كونه متوسطاً مناخياً مرجعياً، وليس دليلاً على أن كمية المطر السنوية لم تتغير. لا يصح استخدامه لقياس جفاف سنة بعينها. تعكس أحدث قيمة سنة 2022، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأغذية والزراعة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأغذية والزراعة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/AG.LND.PRCP.MM?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"battle-related-deaths","intro":"عدد الوفيات المرتبطة مباشرة بالمعارك المسجلة أو المقدرة وفق قواعد تغطية النزاعات في الجهة الناشرة. آخر رقم منشور لليمن هو 918 شخص في سنة القياس 2024 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد في رصد جانب محدد من أثر القتال البشري عبر السنوات، ويمكن مقارنته بمؤشرات النزوح والاحتياجات الإنسانية مع مراعاة اختلاف التعريفات.","historical_context":"من النقاط الزمنية المسجلة: 1994 (1,489 شخص)، و2015 (7,720 شخص)، و2024 (918 شخص). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا يساوي كل ضحايا الحرب أو الوفيات غير المباشرة بسبب الجوع والمرض وانهيار الخدمات، وقد تكون التغطية ناقصة في مناطق يصعب الرصد فيها. يجب عدم تحويله إلى حصيلة شاملة. تعكس أحدث قيمة سنة 2024، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مصادر النزاع والأمن عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مصادر النزاع والأمن عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/VC.BTL.DETH?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"control-of-corruption-score","intro":"درجة مركبة في مؤشرات الحوكمة العالمية تتعلق بمدى السيطرة على استغلال السلطة العامة لتحقيق مكاسب خاصة وفق مصادر الجهة الناشرة. آخر رقم منشور لليمن هو 14.17 درجة معيارية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تساعد في مناقشة النزاهة والرقابة والمحاسبة ومخاطر الفساد على الخدمات والتعاملات الاقتصادية.","historical_context":"من النقاط الزمنية المسجلة: 1996 (33.97 درجة معيارية)، و2012 (22.93 درجة معيارية)، و2025 (14.17 درجة معيارية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا تحدد مقدار الأموال المختلسة أو عدد قضايا الفساد المثبتة، ولا تمثل تصويتاً مباشراً لجميع المواطنين. ينبغي التعامل مع عدم اليقين واختلاف مصادر التقدير. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مؤشرات الحوكمة العالمية WGI. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مؤشرات الحوكمة العالمية WGI — صفحة المؤشر","url":"https://data.worldbank.org/indicator/GOV_WGI_CC_SC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"forest-area-share","intro":"نسبة مساحة الأراضي المصنفة غابات من مساحة اليابسة وفق تعريف الكثافة والامتداد النباتي للمصدر، وليس نسبة كل المساحات الخضراء. آخر رقم منشور لليمن هو 1.04 % من مساحة اليابسة في سنة القياس 2024 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تساعد في متابعة أحد مكونات الغطاء الطبيعي ومناقشة الموائل والأخشاب والتربة والاحتفاظ بالمياه.","historical_context":"من النقاط الزمنية المسجلة: 1990 (1.04 % من مساحة اليابسة)، و2007 (1.04 % من مساحة اليابسة)، و2024 (1.04 % من مساحة اليابسة). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا تشمل بالضرورة الأشجار المتفرقة أو الأراضي الزراعية، ولا تخبرنا بصحة الغابة أو معدل قطع الأشجار. تقارب الأرقام عبر السنوات ليس دليلاً على غياب تغير محلي. تعكس أحدث قيمة سنة 2024، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأغذية والزراعة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأغذية والزراعة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/AG.LND.FRST.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"government-effectiveness-score","intro":"درجة مركبة لتقدير فاعلية الإدارة العامة والخدمات وتنفيذ السياسات وفق منهجية مؤشرات الحوكمة العالمية. آخر رقم منشور لليمن هو 14.03 درجة معيارية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تستخدم لفهم التحديات المؤسسية العامة وجودة التنفيذ والخدمات في إطار مقارنات دولية، مع ضرورة تحليل القطاعات كل على حدة.","historical_context":"من النقاط الزمنية المسجلة: 1996 (31.61 درجة معيارية)، و2012 (28.61 درجة معيارية)، و2025 (14.03 درجة معيارية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا تقيس أداء كل مستشفى أو مدرسة أو وزارة مباشرة، ولا تكشف وحدها سبب ضعف الخدمة. الدرجات ليست نسبة مئوية للخدمات الناجحة. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مؤشرات الحوكمة العالمية WGI. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مؤشرات الحوكمة العالمية WGI — صفحة المؤشر","url":"https://data.worldbank.org/indicator/GOV_WGI_GE_SC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"high-technology-exports","intro":"قيمة صادرات المنتجات المصنفة عالية التقنية بالدولار الجاري ضمن قائمة فئات سلعية تستخدمها الجهة الإحصائية. آخر رقم منشور لليمن هو 3.03 مليون دولار في سنة القياس 2015 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد على وصف جانب ضيق من تركيبة الصادرات ذات الكثافة التقنية ومناقشة تنويع الاقتصاد والإنتاج الصناعي.","historical_context":"من النقاط الزمنية المسجلة: 2009 (382,625 دولار أمريكي)، و2012 (584,721 دولار أمريكي)، و2015 (3.03 مليون دولار). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا يساوي صادرات البرمجيات والخدمات الرقمية كلها، ولا قيمة الشركات الناشئة أو مستوى الابتكار المحلي. وقد تتغير القيمة بسبب شحنة كبيرة واحدة في اقتصاد صغير المصدر. آخر قيمة تخص 2015، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: المنظمة العالمية للملكية الفكرية عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"المنظمة العالمية للملكية الفكرية عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/TX.VAL.TECH.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"intentional-homicide-rate","intro":"عدد ضحايا جرائم القتل العمد لكل 100 ألف شخص خلال سنة وفق التعريف الجنائي والإحصائي للمصدر. آخر رقم منشور لليمن هو 5.81 لكل 100 ألف شخص في سنة القياس 2013 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد في دراسة جانب من العنف الجنائي والسلامة العامة بصورة قابلة للمقارنة بعد مراعاة جودة التسجيل.","historical_context":"من النقاط الزمنية المسجلة: 1998 (3.33 لكل 100 ألف شخص)، و2004 (2.92 لكل 100 ألف شخص)، و2013 (5.81 لكل 100 ألف شخص). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا يساوي عدد قتلى المعارك أو الوفيات في الكوارث أو كل حالات العنف. يمكن أن يقلل ضعف الإبلاغ أو اختلاف التصنيف الجنائي من شمول الرقم. آخر قيمة تخص 2013، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مصادر النزاع والأمن عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مصادر النزاع والأمن عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/VC.IHR.PSRC.P5?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"international-tourism-arrivals","intro":"عدد الزائرين الدوليين الوافدين الذين يستوفون التعريف الإحصائي للسياحة الدولية لدى المصدر خلال سنة. آخر رقم منشور لليمن هو 398,000 زائر في سنة القياس 2015 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يعطي تصوراً عن حجم التدفق السياحي الدولي ضمن السنوات المتاحة، ويمكن ربطه بإيرادات السفر والخدمات السياحية.","historical_context":"من النقاط الزمنية المسجلة: 2010 (1,035,000 زائر)، و2012 (1,282,000 زائر)، و2015 (398,000 زائر). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليس عدد الرحلات الداخلية أو سكان اليمن العائدين بالضرورة، ولا يقيس مدة الإقامة أو متوسط الإنفاق. البيانات التاريخية لا تثبت إمكان السفر حالياً. آخر قيمة تخص 2015، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأمم المتحدة للسياحة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأمم المتحدة للسياحة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ST.INT.ARVL?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"international-tourism-receipts","intro":"إيرادات الزيارات السياحية الدولية الداخلة في تعريف المصدر بالدولار الجاري، لا إجمالي إيراد جميع المنشآت السياحية المحلية. آخر رقم منشور لليمن هو 116.00 مليون دولار في سنة القياس 2016 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تساعد في تتبع العائد الاقتصادي المسجل للسياحة الدولية ومقارنته بأعداد الوافدين وتغير نشاط القطاع عبر السنوات.","historical_context":"من النقاط الزمنية المسجلة: 2010 (1.29 مليار دولار)، و2013 (1.10 مليار دولار)، و2016 (116.00 مليون دولار). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا تشمل تلقائياً إنفاق السياح المحليين أو كل المعاملات غير المرصودة، ولا تُظهر أرباح المنشآت الصافية. وآخر القيمة المنشورة قديم ولا يصف حركة السياحة الحالية. آخر قيمة تخص 2016، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأمم المتحدة للسياحة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأمم المتحدة للسياحة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ST.INT.RCPT.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"marine-protected-areas","intro":"نسبة المساحات البحرية المصنفة قانونياً ضمن مناطق محمية وفق قاعدة بيانات الحماية ذات الصلة، نسبةً إلى المجال البحري الذي تعتمده السلسلة. آخر رقم منشور لليمن هو 0.4 % من المياه الإقليمية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تساعد في متابعة نطاق الحماية المعلنة للموائل البحرية والثروة السمكية والشعاب، ويمكن مقارنتها بالحماية البرية.","historical_context":"من النقاط الزمنية المسجلة: 2013 (0.5 % من المياه الإقليمية)، و2019 (0.5 % من المياه الإقليمية)، و2025 (0.4 % من المياه الإقليمية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"النسبة القانونية لا تؤكد مستوى الالتزام أو الرقابة الميدانية أو تعافي التنوع البيولوجي، وقد تختلف المساحة المحسوبة مع تحديث حدود المناطق والبيانات. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: البنك الدولي - مؤشرات البيئة والمناخ. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البيئة والمناخ — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ER.MRN.PTMR.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"military-expenditure-current-usd","intro":"قيمة الإنفاق العسكري المسجلة أو المقدرة بالدولار الجاري وفق تعريف مصدر البيانات، لا إجمالي التكلفة البشرية والاقتصادية للحرب. آخر رقم منشور لليمن هو 1.71 مليار دولار في سنة القياس 2014 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يمكن أن تضع موارد الأنشطة العسكرية في سياق المالية العامة وأولويات الإنفاق، حين تتوفر بيانات مؤسسية قابلة للمقارنة.","historical_context":"من النقاط الزمنية المسجلة: 1990 (807.07 مليون دولار)، و2002 (737.37 مليون دولار)، و2014 (1.71 مليار دولار). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"القيمة لا تغطي تلقائياً كل الأطراف المسلحة أو مصادر الإنفاق غير المعلنة، ولا تمثل تكلفة الحرب الشاملة. وأحدث بيانات 967 تعود إلى ما قبل مرحلة طويلة من النزاع. آخر قيمة تخص 2014، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مصادر النزاع والأمن عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مصادر النزاع والأمن عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/MS.MIL.XPND.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"military-expenditure-share-gdp","intro":"الإنفاق العسكري كنسبة من الناتج المحلي وفق تعريف النفقات المغطاة بالسلسلة ومقام الناتج في سنة القياس. آخر رقم منشور لليمن هو 3.97 % من الناتج المحلي في سنة القياس 2014 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تعطي تصوراً نسبياً للوزن المالي للإنفاق العسكري مقارنة بحجم الاقتصاد، وتكمل قيمة الإنفاق بالدولار.","historical_context":"من النقاط الزمنية المسجلة: 1990 (6.55 % من الناتج المحلي)، و2002 (6.9 % من الناتج المحلي)، و2014 (3.97 % من الناتج المحلي). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"النسبة قد ترتفع بسبب انخفاض الناتج حتى دون زيادة الإنفاق، ولا تشمل حتماً الإنفاق غير الرسمي أو احتياجات إعادة الإعمار والضحايا. البيانات المعروضة تاريخية. آخر قيمة تخص 2014، ولا يجوز اعتبارها قياساً لواقع 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مصادر النزاع والأمن عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مصادر النزاع والأمن عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/MS.MIL.XPND.GD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"net-official-development-assistance","intro":"صافي المساعدات الإنمائية الرسمية الواردة كما تعرفها إحصاءات الجهات المانحة والبلدان المستفيدة، بعد احتساب التدفقات والخصومات المرتبطة. آخر رقم منشور لليمن هو 4.15 مليار دولار في سنة القياس 2023 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يساعد في فهم حجم أحد مصادر التمويل الخارجي للمشروعات والمساعدات، ويتيح طرح أسئلة عن مجالات الإنفاق وتغير أولويات المانحين.","historical_context":"من النقاط الزمنية المسجلة: 1990 (449.83 مليون دولار)، و2006 (287.81 مليون دولار)، و2023 (4.15 مليار دولار). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"لا يساوي ما وصل نقداً لكل أسرة أو ما أنفقته الحكومة مباشرة. وقد تشمل البيانات قنوات ومنظمات متعددة؛ الصافي ليس مجموع الوعود والتعهدات. تعكس أحدث قيمة سنة 2023، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: لجنة المساعدة الإنمائية عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"لجنة المساعدة الإنمائية عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/DT.ODA.ODAT.CD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"new-conflict-displacements","intro":"عدد حركات النزوح الداخلي الجديدة التي سببها الصراع والعنف خلال سنة كما يسجلها نظام رصد النزوح. آخر رقم منشور لليمن هو 80,000 حالة نزوح في سنة القياس 2023 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يوضح شدة التحركات القسرية الجديدة في الفترات المرصودة ويساعد على مناقشة الحاجة إلى المأوى والغذاء والوثائق والخدمات.","historical_context":"من النقاط الزمنية المسجلة: 2009 (150,000 حالة نزوح)، و2016 (478,000 حالة نزوح)، و2023 (80,000 حالة نزوح). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليس رصيد النازحين الموجودين داخل اليمن عند نهاية العام، وقد ينزح الشخص أكثر من مرة. ولا يشمل تلقائياً اللاجئين العابرين للحدود أو جميع حالات النزوح غير المرصودة. تعكس أحدث قيمة سنة 2023، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مركز رصد النزوح الداخلي IDMC عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مركز رصد النزوح الداخلي IDMC عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/VC.IDP.NWCV?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"new-disaster-displacements","intro":"عدد حالات النزوح الجديدة المرتبطة بالكوارث خلال سنة وفق نظام رصد النزوح، أي الحركات المسجلة وليس العدد الفريد للسكان النازحين. آخر رقم منشور لليمن هو 240,000 حالة نزوح في سنة القياس 2023 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يفيد في إظهار أثر الفيضانات والعواصف وغيرها من الكوارث على انتقال الأسر وحاجتها إلى المأوى والمساعدة والتعافي.","historical_context":"من النقاط الزمنية المسجلة: 2008 (22,000 حالة نزوح)، و2017 (13 حالة نزوح)، و2023 (240,000 حالة نزوح). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"قد يُحسب الشخص أكثر من مرة إذا نزح عدة مرات، لذلك ليست القيمة عدد النازحين المقيمين في المخيمات بنهاية السنة. تقديرات الرصد لا تغطي بالضرورة كل الحوادث. تعكس أحدث قيمة سنة 2023، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مركز رصد النزوح الداخلي IDMC عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مركز رصد النزوح الداخلي IDMC عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/VC.IDP.NWDS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"pm25-air-pollution","intro":"متوسط تعرض السكان لتركيز الجسيمات الدقيقة PM2.5 في الهواء، بوحدة ميكروغرام لكل متر مكعب؛ وهي جسيمات صغيرة يمكن استنشاقها بعمق. آخر رقم منشور لليمن هو 46.84 ميكروغرام لكل متر مكعب في سنة القياس 2023 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يوضح أحد جوانب جودة الهواء التي تستحق الدراسة الصحية والبيئية، ويساعد على تحديد الحاجة إلى بيانات رصد أكثر محلية.","historical_context":"من النقاط الزمنية المسجلة: 1990 (44.76 ميكروغرام لكل متر مكعب)، و2006 (39.47 ميكروغرام لكل متر مكعب)، و2023 (46.84 ميكروغرام لكل متر مكعب). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"المتوسط الوطني لا يصف تركيز الهواء في شارع بعينه أو يوم محدد، ولا يحدد مصدر التلوث مثل النقل أو الغبار. قد يعتمد التقدير على نماذج وملاحظات متفرقة. تعكس أحدث قيمة سنة 2023، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: البنك الدولي - مؤشرات البيئة والمناخ. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البيئة والمناخ — صفحة المؤشر","url":"https://data.worldbank.org/indicator/EN.ATM.PM25.MC.M3?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"political-stability-score","intro":"درجة مركبة من تقديرات مؤشرات الحوكمة العالمية تقارب تصور مخاطر عدم الاستقرار السياسي والعنف، بحسب مقياس الناشر وإصداره. آخر رقم منشور لليمن هو 21.69 درجة معيارية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"توفر إطاراً لمناقشة استقرار المؤسسات والمخاطر السياسية في مقارنة منهجية، ولكن ينبغي ربطها بوقائع موثقة ومصادر إضافية.","historical_context":"من النقاط الزمنية المسجلة: 1996 (32.71 درجة معيارية)، و2012 (24.16 درجة معيارية)، و2025 (21.69 درجة معيارية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليست نسبة السكان الآمنين ولا احتمالاً رقمياً مباشراً لاندلاع حرب. درجات الحوكمة تعتمد على مصادر ومقاييس إدراكية وتقديرات، وقد تُعاد مراجعتها عبر الإصدارات. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مؤشرات الحوكمة العالمية WGI. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مؤشرات الحوكمة العالمية WGI — صفحة المؤشر","url":"https://data.worldbank.org/indicator/GOV_WGI_PV_SC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"renewable-internal-freshwater-per-capita","intro":"حجم موارد المياه العذبة المتجددة المتولدة داخل البلاد محسوباً للفرد الواحد، وفق تقديرات المورد المائي وعدد السكان. آخر رقم منشور لليمن هو 54.94 متر مكعب للفرد في سنة القياس 2022 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يضع محدودية الموارد المائية في سياق الحجم السكاني، ويساعد على فهم ضغط الاحتياجات المنزلية والزراعية والإنتاجية على الإمدادات.","historical_context":"من النقاط الزمنية المسجلة: 1990 (151.21 متر مكعب للفرد)، و2006 (89.2 متر مكعب للفرد)، و2022 (54.94 متر مكعب للفرد). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليس مقدار المياه التي تصل إلى كل شخص عبر الشبكة ولا يقيس جودة المياه أو مستوى المخزون الجوفي. قد ينخفض نصيب الفرد مع نمو السكان حتى لو لم ينخفض إجمالي التجدد الطبيعي. تعكس أحدث قيمة سنة 2022، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: منظمة الأغذية والزراعة عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"منظمة الأغذية والزراعة عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ER.H2O.INTR.PC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"resident-patent-applications","intro":"عدد طلبات براءات الاختراع المقدمة من مقيمين وفق تعريف الجهة المختصة والبيانات المستخدمة، وليس عدد البراءات الممنوحة. آخر رقم منشور لليمن هو 11 طلب في سنة القياس 2023 ضمن سلسلة الجهة الناشرة.","why_it_matters":"يوفر دلالة جزئية على نشاط طلب الحماية القانونية للاختراعات، ويتيح مناقشة بيئة البحث والتطوير والحوافز المؤسسية.","historical_context":"من النقاط الزمنية المسجلة: 1998 (7 طلب)، و2011 (7 طلب)، و2023 (11 طلب). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"تقديم الطلب لا يعني الموافقة عليه أو استخدام الاختراع تجارياً، ولا تشمل الأرقام تلقائياً الأفكار غير المسجلة. وقد تتأثر بالمؤسسات وقواعد الإيداع. تعكس أحدث قيمة سنة 2023، ولا تثبت استمرار هذه الحالة في 2026. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: المنظمة العالمية للملكية الفكرية عبر البنك الدولي. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"المنظمة العالمية للملكية الفكرية عبر البنك الدولي — صفحة المؤشر","url":"https://data.worldbank.org/indicator/IP.PAT.RESD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"rule-of-law-score","intro":"درجة مركبة لتقديرات سيادة القانون وفق مؤشرات الحوكمة العالمية، بما في ذلك الثقة بتطبيق القواعد وحماية الحقوق ضمن منهجية المصدر. آخر رقم منشور لليمن هو 26.62 درجة معيارية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تعطي مدخلاً لمناقشة انتظام المؤسسات القضائية والتنفيذية وأمن التعاملات، ويُستكمل ذلك بأبحاث ميدانية وبيانات قضائية.","historical_context":"من النقاط الزمنية المسجلة: 1996 (38.1 درجة معيارية)، و2012 (36.31 درجة معيارية)، و2025 (26.62 درجة معيارية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليست عدداً للقضايا المحسومة أو مدة التقاضي ولا حكماً قانونياً نهائياً على الدولة. تتأثر الدرجات بمصادر مختلفة وعدم اليقين المنهجي. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مؤشرات الحوكمة العالمية WGI. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مؤشرات الحوكمة العالمية WGI — صفحة المؤشر","url":"https://data.worldbank.org/indicator/GOV_WGI_RL_SC?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"terrestrial-protected-areas","intro":"حصة مساحة الأراضي التي تقع ضمن المناطق الطبيعية البرية المصنفة محمية في قواعد البيانات الدولية المستخدمة. آخر رقم منشور لليمن هو 1.1 % من مساحة الأرض في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تبيّن اتساع المساحات التي تتمتع بوضع حماية رسمي، وتساعد في مناقشة الحفاظ على الأنواع والموائل والغطاء النباتي.","historical_context":"من النقاط الزمنية المسجلة: 2013 (0.8 % من مساحة الأرض)، و2019 (0.8 % من مساحة الأرض)، و2025 (1.1 % من مساحة الأرض). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"إعلان الحماية لا يثبت أن جميع المواقع مُدارة بفاعلية أو أن التنوع الحيوي فيها آمن. ولا تشمل النسبة وحدها الحماية المجتمعية غير المسجلة. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: البنك الدولي - مؤشرات البيئة والمناخ. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البيئة والمناخ — صفحة المؤشر","url":"https://data.worldbank.org/indicator/ER.LND.PTLD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"voice-accountability-score","intro":"درجة مركبة في مؤشرات الحوكمة العالمية تتعلق بإمكان مشاركة المواطنين والمساءلة والحريات ذات الصلة وفق منهجية الجهة المنتجة. آخر رقم منشور لليمن هو 25.67 درجة معيارية في سنة القياس 2025 ضمن سلسلة الجهة الناشرة.","why_it_matters":"تفيد في طرح أسئلة عن التمثيل والمشاركة والرقابة العامة وحرية التعبير، مع الاعتراف بتعدد الأبعاد التي يغطيها المؤشر.","historical_context":"من النقاط الزمنية المسجلة: 1996 (39.61 درجة معيارية)، و2012 (35.22 درجة معيارية)، و2025 (25.67 درجة معيارية). ينبغي الرجوع إلى السلسلة الكاملة لمعرفة التقلبات والفجوات؛ والأرقام وحدها لا تفسر أسباب تغيرها.","limitations":"ليست نتيجة انتخابات أو استطلاع وطني واحد، ولا تمثل نسبة المواطنين المشاركين في السياسة. لا يجوز مقارنة قيم الإصدارات دون فحص مقياس السلسلة. ولا يثبت هذا الرقم بمفرده علاقة سببية مع أي ظاهرة أخرى.","source_notes":"المصدر المرتبط بالسلسلة داخل 967: مؤشرات الحوكمة العالمية WGI. الأرقام مأخوذة من سجلات القياسات الوطنية التي راجعتها مبادرة 967 بتاريخ 2026-10-27، وقد تعتمد على تقديرات أو تعريفات لا تطابق البيانات المحلية الأخرى. هذه المراجعة تحريرية للمحتوى المسجل وليست مسحاً ميدانياً جديداً.","reference_links":[{"title":"مؤشرات الحوكمة العالمية WGI — صفحة المؤشر","url":"https://data.worldbank.org/indicator/GOV_WGI_VA_SC?locations=YE"}],"reviewed_on":"2026-10-27"}]'::jsonb) AS d),
inserted AS (
 INSERT INTO public.stat_indicator_editorial(indicator_id,intro,why_it_matters,historical_context,limitations,source_notes,reference_links,reviewed_on,is_published)
 SELECT i.id,p.d->>'intro',p.d->>'why_it_matters',p.d->>'historical_context',p.d->>'limitations',p.d->>'source_notes',p.d->'reference_links',(p.d->>'reviewed_on')::date,true
 FROM prepared p JOIN public.stat_indicators i ON i.slug=p.d->>'slug' WHERE i.is_published AND i.slug<>'access-to-electricity'
 ON CONFLICT(indicator_id) DO NOTHING RETURNING indicator_id
) SELECT (SELECT count(*) FROM prepared) AS prepared,(SELECT count(*) FROM inserted) AS inserted;